@androidx.media3.common.util.UnstableApi
public class DeleteMediaTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private Activity activity,child;private final List<Uri> fixtures=new ArrayList<>();private final Map<String,Map<String,?>> saved=new HashMap<>();
 private Object get(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 private interface Check{boolean ok()throws Exception;}
 private void waitFor(Check check)throws Exception{long until=SystemClock.elapsedRealtime()+25000;while(SystemClock.elapsedRealtime()<until){boolean[] ok={false};ins.runOnMainSync(()->{try{ok[0]=check.ok();}catch(Exception e){throw new RuntimeException(e);}});if(ok[0])return;Thread.sleep(100);}String[] state={""};ins.runOnMainSync(()->{try{if(child!=null)state[0]=" phase="+get(child,"phase")+" ready="+get(child,"ready")+" busy="+get(child,"busy")+" finishing="+child.isFinishing()+" details="+((TextView)get(child,"details")).getText();}catch(Exception e){state[0]=e.toString();}});AccessibilityNodeInfo root=ins.getUiAutomation().getRootInActiveWindow();throw new AssertionError("Deletion UI timed out"+state[0]+" window="+(root==null?"null":root.getPackageName())+" tree="+tree(root,0));}
 private Uri fixture(boolean video)throws Exception{ContentValues v=new ContentValues();String name="Onda-delete-native-"+UUID.randomUUID();v.put("_display_name",name+(video?".mp4":".m4a"));v.put("title",name);v.put("mime_type",video?"video/mp4":"audio/mp4");v.put("duration",3000);v.put("relative_path",video?"Movies/OndaTest":"Music/OndaTest");v.put("is_pending",1);Uri uri=c.getContentResolver().insert(video?MediaStore.Video.Media.EXTERNAL_CONTENT_URI:MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,v);assertNotNull(uri);fixtures.add(uri);try(InputStream in=ins.getContext().getAssets().open(video?"combined.mp4":"audio.m4a");OutputStream out=c.getContentResolver().openOutputStream(uri)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}v.clear();v.put("is_pending",0);c.getContentResolver().update(uri,v,null,null);return uri;}
 private boolean exists(Uri uri){try(Cursor q=c.getContentResolver().query(uri,new String[]{"_id"},null,null,null)){return q!=null&&q.moveToFirst();}}
 private String tree(AccessibilityNodeInfo node,int depth){if(node==null||depth>8)return "";StringBuilder text=new StringBuilder();text.append("[").append(node.getText()).append("/").append(node.getViewIdResourceName()).append("]");for(int i=0;i<node.getChildCount()&&text.length()<5000;i++)text.append(tree(node.getChild(i),depth+1));return text.toString();}
 private boolean clickNode(AccessibilityNodeInfo node,String... texts){if(node==null)return false;String text=node.getText()==null?"":node.getText().toString();for(String t:texts)if(text.equalsIgnoreCase(t)){Rect bounds=new Rect();node.getBoundsInScreen(bounds);if(!node.isVisibleToUser()||bounds.isEmpty())continue;long time=SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(time,time,android.view.MotionEvent.ACTION_DOWN,bounds.exactCenterX(),bounds.exactCenterY(),0),up=android.view.MotionEvent.obtain(time,time+1,android.view.MotionEvent.ACTION_UP,bounds.exactCenterX(),bounds.exactCenterY(),0);down.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);up.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);try{if(ins.getUiAutomation().injectInputEvent(down,true)&&ins.getUiAutomation().injectInputEvent(up,true))return true;}finally{down.recycle();up.recycle();}}for(int i=0;i<node.getChildCount();i++)if(clickNode(node.getChild(i),texts))return true;return false;}
 private void click(String... texts)throws Exception{long end=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<end){if(clickNode(ins.getUiAutomation().getRootInActiveWindow(),texts)){Thread.sleep(300);return;}Thread.sleep(150);}AccessibilityNodeInfo root=ins.getUiAutomation().getRootInActiveWindow();throw new AssertionError("Missing dialog action "+Arrays.toString(texts)+" tree="+tree(root,0));}
 private void approve()throws Exception{waitFor(()->(Boolean)get(child,"ready"));ins.runOnMainSync(()->{try{((Button)get(child,"remove")).performClick();}catch(Exception e){throw new RuntimeException(e);}});if(Build.VERSION.SDK_INT>=30)click("Delete","Excluir","Allow","Permitir");waitFor(()->child.isFinishing()||child.isDestroyed());}
 @Before public void before(){for(String n:Arrays.asList("library","downloads","downloaded_audio"))saved.put(n,c.getSharedPreferences(n,0).getAll());c.getSharedPreferences("library",0).edit().putBoolean("downloads_only",false).putInt("sort_order",0).commit();}
 @After public void after(){if(child!=null&&!child.isDestroyed())ins.runOnMainSync(()->child.finish());if(activity!=null&&!activity.isDestroyed())ins.runOnMainSync(()->{try{if(activity instanceof MainActivity){MediaController p=(MediaController)get(activity,"player");if(p!=null){p.pause();p.clearMediaItems();}}}catch(Exception ignored){}activity.finish();});ins.waitForIdleSync();for(Uri u:fixtures)try{c.getContentResolver().delete(u,null,null);}catch(Exception ignored){}for(Map.Entry<String,Map<String,?>> entry:saved.entrySet()){SharedPreferences.Editor e=c.getSharedPreferences(entry.getKey(),0).edit().clear();for(Map.Entry<String,?> item:entry.getValue().entrySet()){Object v=item.getValue();String k=item.getKey();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Set)e.putStringSet(k,new HashSet<>((Set<String>)v));}e.commit();}}
 @Test public void cancellationAndUnsupportedAddressesNeverDeleteFiles()throws Exception{Uri uri=fixture(false);String id=uri.getLastPathSegment();c.getSharedPreferences("library",0).edit().putStringSet("favorites",new HashSet<>(Collections.singletonList(id))).commit();Intent intent=new Intent(c,DeleteMediaActivity.class).setData(uri).putExtra("kind","audio").putExtra("item_id",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);child=ins.startActivitySync(intent);waitFor(()->(Boolean)get(child,"ready"));ins.runOnMainSync(()->{try{((Button)get(child,"cancel")).performClick();}catch(Exception e){throw new RuntimeException(e);}});assertTrue(exists(uri));assertTrue(c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()).contains(id));if(Build.VERSION.SDK_INT>=30){child=ins.startActivitySync(intent);waitFor(()->(Boolean)get(child,"ready"));ins.runOnMainSync(()->{try{((Button)get(child,"remove")).performClick();}catch(Exception e){throw new RuntimeException(e);}});click("Deny","Negar","Don’t allow","Don't allow","Não permitir","Cancel","Cancelar");waitFor(()->child.isFinishing());assertTrue(exists(uri));assertTrue(c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()).contains(id));}child=ins.startActivitySync(new Intent(c,DeleteMediaActivity.class).setData(Uri.parse("https://example.com/audio.mp3")).putExtra("kind","audio").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.waitForIdleSync();assertFalse((Boolean)get(child,"ready"));assertTrue(exists(uri));}
 @Test public void longPressAudioDeletesOnlySelectedFileAndClearsItsQueueAndFavorite()throws Exception{Uri uri=fixture(false),other=fixture(false);String id=uri.getLastPathSegment();c.getSharedPreferences("library",0).edit().putStringSet("favorites",new HashSet<>(Collections.singletonList(id))).commit();DownloadedAudio.remember(c,uri.toString(),"Deletion fixture","audio/mp4");c.getSharedPreferences("downloads",0).edit().putString("last_uri",uri.toString()).putString("last_mime","audio/mp4").commit();activity=ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->get(activity,"player")!=null&&(Boolean)get(activity,"libraryReady"));MediaItem target=new MediaItem.Builder().setMediaId(id).setUri(uri).setMediaMetadata(new MediaMetadata.Builder().setTitle("Delete selected audio").build()).build();
  ins.runOnMainSync(()->{try{List<MediaItem> songs=(List<MediaItem>)get(activity,"songs");songs.clear();songs.add(target);((EditText)get(activity,"localSearch")).setText("Delete selected audio");MediaController player=(MediaController)get(activity,"player");player.setMediaItems(Arrays.asList(target,MediaItem.fromUri(other)));}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->{ListView list=(ListView)get(activity,"libraryList");if(list.getChildCount()==0||!(list.getChildAt(0) instanceof FrameLayout))return false;FrameLayout row=(FrameLayout)list.getChildAt(0);return row.getChildCount()>0&&String.valueOf(row.getChildAt(0).getContentDescription()).contains("Delete selected audio");});Instrumentation.ActivityMonitor monitor=ins.addMonitor(DeleteMediaActivity.class.getName(),null,false);ins.runOnMainSync(()->{try{FrameLayout row=(FrameLayout)((ListView)get(activity,"libraryList")).getChildAt(0);row.getChildAt(0).performLongClick();}catch(Exception e){throw new RuntimeException(e);}});click("Excluir arquivo do celular…");child=monitor.waitForActivityWithTimeout(15000);ins.removeMonitor(monitor);assertNotNull(child);approve();waitFor(()->!exists(uri));waitFor(()->{MediaController p=(MediaController)get(activity,"player");return p.getMediaItemCount()==1&&p.getCurrentMediaItem().localConfiguration.uri.equals(other);});assertTrue(exists(other));assertFalse(c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()).contains(id));assertFalse(c.getSharedPreferences("downloaded_audio",0).getString("documents","{}").contains(uri.toString()));assertFalse(c.getSharedPreferences("downloads",0).contains("last_uri"));}
 @Test public void longPressVideoDeletesOnlySelectedFileAndRefreshesList()throws Exception{Uri uri=fixture(true),other=fixture(true);activity=ins.startActivitySync(new Intent(c,VideoActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->((List<?>)get(activity,"videos")).stream().anyMatch(o->((VideoStore.Item)o).uri.equals(uri)));ins.runOnMainSync(()->{try{VideoStore.Item item=((List<VideoStore.Item>)get(activity,"videos")).stream().filter(o->o.uri.equals(uri)).findFirst().get();((EditText)get(activity,"search")).setText(item.title);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->((ListView)get(activity,"videoList")).getChildCount()>0&&((List<?>)get(activity,"visible")).size()==1);Instrumentation.ActivityMonitor monitor=ins.addMonitor(DeleteMediaActivity.class.getName(),null,false);ins.runOnMainSync(()->{try{ListView list=(ListView)get(activity,"videoList");list.getOnItemLongClickListener().onItemLongClick(list,list.getChildAt(0),0,0);}catch(Exception e){throw new RuntimeException(e);}});click("Excluir arquivo do celular…");child=monitor.waitForActivityWithTimeout(15000);ins.removeMonitor(monitor);assertNotNull(child);approve();waitFor(()->!exists(uri));waitFor(()->((List<?>)get(activity,"visible")).isEmpty());assertTrue(exists(other));}
}
